package br.gov.dere.persistence;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="dere_batch") public class DereBatchEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String protocol; @Enumerated(EnumType.STRING) private br.gov.dere.domain.EventStatus status; @Lob @Column(name="request_xml",nullable=false) private String requestXml; @Lob private String responseXml; @Column(name="created_at") private Instant createdAt=Instant.now(); private Instant sentAt; private Instant lastQueryAt; protected DereBatchEntity(){} public DereBatchEntity(String xml){requestXml=xml;status=br.gov.dere.domain.EventStatus.BATCHED;} public Long getId(){return id;} public String getProtocol(){return protocol;} public br.gov.dere.domain.EventStatus getStatus(){return status;} public String getRequestXml(){return requestXml;} public void received(String p){protocol=p;status=br.gov.dere.domain.EventStatus.PROCESSING;sentAt=Instant.now();} public void completed(br.gov.dere.domain.EventStatus s,String response){status=s;responseXml=response;lastQueryAt=Instant.now();} }
